/// <summary>
/// Data contract class as a response for service <c>METPurchaseOrderReceiptContract</c>
/// CB256_PurchaseOrderReceiptDetails by Akshay
/// </summary>
[DataContractAttribute]
class METPurchaseOrderReceiptResponseContract extends METBaseResponseContract
{
}

Method.Source:
    /// <summary>
    /// Contruct a new Response contract
    /// </summary>
    /// <param name = "_result">Result of the cancellation</param>
    /// <param name = "_mssage">Message Result</param>
    /// <returns>new contract</returns>
    public static METPurchaseOrderReceiptResponseContract newFromParameters(METProcessingStatus _result, Description255 _message)
    {
        METPurchaseOrderReceiptResponseContract response = new METPurchaseOrderReceiptResponseContract();

        response.parmResult(enum2Symbol(enumNum(METProcessingStatus), enum2int(_result)));
        response.parmMessage(_message);

        return response;
    }
